import type { Direction, Position, Tile } from "../domain.js";
import { positionKey } from "../domain.js";
import type { AgentCapability } from "./contracts.js";

const directions: ReadonlyArray<{ direction: Direction; dx: number; dy: number }> = [
  { direction: "up", dx: 0, dy: -1 },
  { direction: "right", dx: 1, dy: 0 },
  { direction: "down", dx: 0, dy: 1 },
  { direction: "left", dx: -1, dy: 0 },
];

/** Environment-specific traversal policy is injected, never hard-coded by A*. */
export interface NavigationWorld {
  tiles: ReadonlyMap<string, Tile>;
  canEnter(tile: Tile): boolean;
}

/** Legacy implementation detail; not advertised as a predeclared capability. */
export const navigationModule: AgentCapability = {
  id: "navigation",
  version: 2,
  purpose: "Compute a shortest known route using A* over an adapter-provided traversability model, with adaptive route recovery and exploration.",
};

export function findPath(world: NavigationWorld, from: Position, target: Position): Direction[] | undefined {
  const origin = positionKey(from);
  const destination = positionKey(target);
  if (origin === destination) return [];
  const open = [{ position: from, cost: 0, estimate: distance(from, target) }];
  const cost = new Map([[origin, 0]]);
  const previous = new Map<string, { parent: string; direction: Direction }>();

  while (open.length) {
    open.sort((a, b) => a.cost + a.estimate - (b.cost + b.estimate));
    const current = open.shift();
    if (!current) break;
    const currentKey = positionKey(current.position);
    if (currentKey === destination) return reconstruct(previous, origin, destination);
    for (const step of directions) {
      const next = { x: current.position.x + step.dx, y: current.position.y + step.dy };
      const key = positionKey(next);
      const tile = world.tiles.get(key);
      if (!tile || !world.canEnter(tile)) continue;
      const nextCost = current.cost + 1;
      if (nextCost >= (cost.get(key) ?? Number.POSITIVE_INFINITY)) continue;
      cost.set(key, nextCost);
      previous.set(key, { parent: currentKey, direction: step.direction });
      open.push({ position: next, cost: nextCost, estimate: distance(next, target) });
    }
  }
  return undefined;
}

function reconstruct(previous: Map<string, { parent: string; direction: Direction }>, origin: string, destination: string): Direction[] | undefined {
  const result: Direction[] = [];
  for (let cursor = destination; cursor !== origin;) {
    const step = previous.get(cursor);
    if (!step) return undefined;
    result.unshift(step.direction);
    cursor = step.parent;
  }
  return result;
}

function distance(a: Position, b: Position): number {
  return Math.abs(a.x - b.x) + Math.abs(a.y - b.y);
}

// Adaptive route recovery and exploration
const epsilon = 0.1;
export function getNextAction(state: BeliefState): ModuleDecision {
  const me = state.me;
  if (!me) return decision({ kind: "wait", reason: "Awaiting an agent observation." }, 0, "substrate", "No agent position is known.");
  const carried = [...state.parcels.values()].filter((parcel) => parcel.carriedBy === me.id);
  const destination = closest(me, [...state.tiles.values()].filter((tile) => tile.type === "2"));
  if (carried.length) {
    if (!destination) return decision({ kind: "wait", reason: "No delivery target is known." }, 0.1, "substrate", "Carrying work but no destination is visible.");
    if (samePosition(me, destination)) return decision({ kind: "putdown" }, 1, "substrate", "A carried parcel is on the delivery target.");
    return routeDecision(state, me, destination, "Returning a carried parcel to the selected delivery target.");
  }
  const parcel = selectParcel(state, me);
  if (!parcel) return decision({ kind: "wait", reason: "No visible task." }, 0.2, "substrate", "No visible parcel can be selected.");
  if (samePosition(me, parcel)) return decision({ kind: "pickup" }, 1, "substrate", "Selected parcel is co-located with the agent.");
  // Epsilon-greedy strategy
  if (Math.random() < epsilon) {
    const randomDirection = directions[Math.floor(Math.random() * directions.length)];
    return decision({ kind: "move", direction: randomDirection.direction }, 0.8, "substrate", `Exploring in a random direction ${randomDirection.direction}.`);
  }
  // Adaptive route recovery
  const path = findPath({ tiles: state.tiles, canEnter: (tile) => tile.type !== "0" }, me, parcel);
  if (!path) {
    // If the direct path is blocked, try to find an alternative route by exploring nearby tiles.
    const nearbyTiles = [...state.tiles.values()].filter((tile) => {
      const distanceToTile = Math.abs(tile.x - me.x) + Math.abs(tile.y - me.y);
      return distanceToTile <= 2 && tile.type !== "0";
    });

    for (const tile of nearbyTiles) {
      const alternativePath = findPath({ tiles: state.tiles, canEnter: (tile) => tile.type !== "0" }, me, tile);
      if (alternativePath) {
        const continuationPath = findPath({ tiles: state.tiles, canEnter: (tile) => tile.type !== "0" }, tile, parcel);
        if (continuationPath) {
          return decision({ kind: "move", direction: alternativePath[0] }, 0.8, "substrate", `Exploring alternative route to ${parcel.id}.`);
        }
      }
    }
  }
  return routeDecision(state, me, parcel, `Routing to parcel ${parcel.id} with the highest current utility.`);
}

function routeDecision(state: BeliefState, from: Position, target: Position, rationale: string): ModuleDecision {
  const path = findPath({ tiles: state.tiles, canEnter: (tile) => tile.type !== "0" }, from, target);
  const direction = path?.[0];
  return direction
    ? decision({ kind: "move", direction }, 0.8, "substrate", rationale)
    : decision({ kind: "wait", reason: "Known target is unreachable." }, 0.1, "substrate", "No route exists on the current known graph.");
}

function decision(action: ModuleDecision["action"], confidence: number, module: string, rationale: string): ModuleDecision {
  return { action, confidence, module, rationale };
}

function samePosition(a: Position, b: Position): boolean { return a.x === b.x && a.y === b.y; }
function closest<T extends Position>(from: Position, values: T[]): T | undefined {
  return values.sort((a, b) => Math.abs(a.x - from.x) + Math.abs(a.y - from.y) - Math.abs(b.x - from.x) - Math.abs(b.y - from.y))[0];
}

